{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 쿼리의 병목에 맞는 개선 방법을 선택할 수 있는지 평가한다. 실행 계획에서 확인한 문제와 조회 조건에 맞는 인덱스를 추가한 판단의 연결에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 3.2초 걸렸고, 실행 계획에서 신고 테이블과 판매글 테이블을 매번 전체 조인하는 것을 확인했다.",
          "task": "조회 조건에 맞는 인덱스를 추가하고 조인 순서를 정리하는 작업을 했다.",
          "action": "실행 계획과 조회 조건에서 어떤 정보를 보고 인덱스 추가가 필요하다고 판단했는지 설명한다.",
          "result": "선택한 인덱스가 확인한 병목을 줄이는 데 적합하다고 본 근거를 설명한다."
        },
        "expectedEvidence": [
          "조회 조건에 맞는 인덱스를 추가한 판단 근거",
          "그 판단을 뒷받침한 실행 계획의 정보",
          "조회 조건과 선택한 인덱스의 관계"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리의 실행 계획을 보셨을 때, 조회 조건에 맞는 인덱스를 추가한 근거는 무엇이었나요?",
      "answerTip": "떠올린 내용을 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 병목을 구체적으로 짚어 인덱스를 추가한 근거를 설명한다.",
            "조회 조건과 선택한 인덱스를 연결해 해당 인덱스가 불필요한 데이터 탐색을 줄이는 데 적합했던 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "조회 속도나 데이터 탐색량을 줄이려는 이유로 인덱스를 추가했다고 답하지만 실행 계획의 정보와 연결이 구체적이지 않다.",
            "조회 조건에 맞춰 인덱스를 골랐다고 설명하지만 해당 조건에 적합했던 근거는 일부만 제시한다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스를 추가한 근거 없이 적용 사실이나 응답 시간 단축 결과만 반복한다.",
            "인덱스는 항상 조회를 빠르게 한다는 일반론에 머물거나 조회 조건과 무관한 설명을 한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 찾은 장애 원인을 같은 장애의 재발을 막는 방안에 연결할 수 있는지 평가한다. 스케줄러 중복 실행 원인을 배포 체크리스트의 점검 대상으로 삼은 판단에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 알림 중복 발송 문의를 받고 로그를 시간순으로 확인해 스케줄러가 서버 두 대에서 동시에 실행되는 것을 찾았다.",
          "task": "잠금 키를 두는 방식으로 수정했고, 배포 체크리스트에 스케줄러 항목을 넣었다.",
          "action": "확인한 장애 원인과 연결해 배포 체크리스트에 스케줄러 항목을 넣은 근거를 설명한다.",
          "result": "체크리스트의 스케줄러 항목이 같은 장애의 재발을 막는 데 도움이 된다고 본 이유를 설명한다."
        },
        "expectedEvidence": [
          "재발 방지용 배포 체크리스트에 스케줄러 항목을 넣은 판단 근거",
          "스케줄러 항목의 필요성을 뒷받침한 장애 원인",
          "해당 항목과 같은 장애의 재발 위험 사이의 연결"
        ]
      },
      "question": "포켓마켓에서 로그로 스케줄러 중복 실행을 찾으셨을 때, 재발 방지용 배포 체크리스트에 스케줄러 항목을 넣은 근거는 무엇이었나요?",
      "answerTip": "생각을 정리한 뒤 편하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "스케줄러 중복 실행이라는 장애 원인을 배포 체크리스트에 스케줄러 항목을 넣은 근거와 구체적으로 연결한다.",
            "배포 시 같은 실행 문제가 반복될 위험을 짚어 해당 체크리스트 항목이 재발 방지에 필요한 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "스케줄러 중복 실행을 다시 놓치지 않으려고 항목을 넣었다고 답하지만 판단 근거가 일반적이다.",
            "체크리스트 항목과 재발 방지의 관계를 설명하지만 같은 장애의 반복 위험과 연결하는 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "스케줄러 항목을 넣은 근거에 답하지 않고 로그 확인이나 잠금 키 수정 사실만 설명한다.",
            "체크리스트가 중요하다는 일반론에 머물거나 스케줄러 중복 실행과 관계없는 이유를 제시한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "사용자 요청을 요구사항으로 구체화할 때 구현 범위를 구분하는 판단을 검증한다. 인터뷰에서 확인한 요청 중 어떤 요구를 범위에 반영할지 결정한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳을 인터뷰했다.",
          "task": "기획 담당으로 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정했다.",
          "action": "인터뷰에서 확인한 요청과 요구사항 범위를 조정한 판단 사이의 연결을 설명한다.",
          "result": "설명한 근거가 해당 요구사항 범위를 선택한 이유를 뒷받침함을 설명한다."
        },
        "expectedEvidence": [
          "요구사항 범위를 조정한 구체적인 판단 근거",
          "범위 판단의 근거가 된 사용자 요청과 필요",
          "범위 선택에 영향을 준 우선순위나 제약"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳을 인터뷰하셨을 때, 요구사항 범위를 조정한 근거는 무엇이었나요?",
      "answerTip": "한 사례를 중심으로 짧게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "요구사항 범위를 조정한 근거를 실제 요청의 내용과 연결해 구체적으로 설명한다.",
            "사용자 필요, 우선순위 또는 제약에 비추어 해당 범위 선택이 타당한 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요구사항 범위를 조정한 근거를 제시하지만 요청과의 연결이 포괄적이다.",
            "필요성이나 제약을 언급하지만 해당 범위를 선택한 이유를 뒷받침하는 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항을 작성하거나 전달했다는 업무 설명만 하고 범위를 조정한 근거는 제시하지 않는다.",
            "범위 판단과 관계없는 성과나 도구 사용을 설명하거나 요청과 맞지 않는 근거를 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "화면 흐름에서 정상 흐름과 구분해야 할 예외 상황을 판단하는 능력을 검증한다. 화면설계서에 포함한 예외 상황을 어떤 근거로 설계했는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 28장을 작성했다.",
          "task": "기획 담당으로 Figma를 사용해 화면설계서를 작성했다.",
          "action": "화면설계서에 담은 예외 상황을 설계한 근거를 해당 화면 흐름의 조건과 연결해 설명한다.",
          "result": "설명한 근거가 정상 흐름과 별도로 예외 상황을 다뤄야 하는 이유를 뒷받침함을 설명한다."
        },
        "expectedEvidence": [
          "예외 상황을 설계한 구체적인 판단 근거",
          "해당 판단의 근거가 된 화면 흐름의 조건",
          "정상 흐름만으로 처리하기 어려웠던 지점"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨을 때, 예외 상황을 설계한 근거는 무엇이었나요?",
      "answerTip": "떠올린 사례를 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제로 설계한 예외 상황의 판단 근거를 화면 흐름의 구체적인 조건과 연결해 설명한다.",
            "해당 조건에서 정상 흐름과 다른 처리가 필요한 이유를 일관되게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황을 설계한 근거를 제시하지만 화면 흐름의 조건에 대한 설명이 포괄적이다.",
            "별도 처리가 필요하다는 설명은 있으나 정상 흐름과 구분한 이유를 뒷받침하는 내용이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 넣었다고만 답하고 설계한 근거는 설명하지 않는다.",
            "화면 흐름의 예외 판단 대신 Figma 사용법이나 화면의 시각적 구성만 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방이 의심스러울 때 그대로 투약하지 않고 확인이 필요하다고 판단할 수 있는지 평가한다. 평소와 다른 진통제 용량을 투약 중단의 근거로 삼은 판단에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 근무 2년 차에 수술 후 환자의 진통제 용량이 평소의 두 배로 처방됐다.",
          "task": "투약 전에 투약을 멈추고 담당의에게 확인했다.",
          "action": "당시 처방 용량에서 무엇을 의심했고 그것이 투약을 멈출 근거가 된 이유를 설명한다.",
          "result": "처방의 정확성을 확인하지 않은 상태에서 투약을 진행할 수 없다고 판단한 이유가 답변에서 드러난다."
        },
        "expectedEvidence": [
          "투약을 멈춰야 한다고 판단한 구체적인 근거",
          "당시 처방 용량과 평소 용량의 차이",
          "용량 차이를 확인 없이 받아들이기 어렵다고 본 이유"
        ]
      },
      "question": "푸른결종합병원에서 진통제 용량이 평소의 두 배로 처방됐을 때, 투약을 멈춰야 한다고 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 상황을 떠올리며 간결하게 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "평소의 두 배인 처방 용량을 구체적으로 짚으며 투약을 멈춘 판단 근거를 설명한다.",
            "평소와 다르다는 사실만으로 오류를 단정하지 않으면서도 처방의 정확성이 확인되지 않아 투약을 보류해야 한다는 판단을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 다른 용량이어서 확인이 필요했다고 투약 중단의 근거를 제시한다.",
            "용량 차이와 투약 중단을 연결하지만 확인 없이 투약하기 어렵다고 본 이유는 일반적인 안전 원칙 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 사실이나 이후 입력 오류였다는 결과만 말하고 당시 판단 근거를 설명하지 못한다.",
            "용량이 의심스러워도 처방대로 투약하면 된다고 말하거나 투약 중단 판단과 무관한 일반론으로 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태와 관련된 정보를 다음 근무자에게 빠짐없이 전달할 수 있는지 평가한다. 진통제 투여 시각과 보행 보조 여부를 인수인계 항목으로 고른 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동 QI 활동에서 사고 보고서를 통해 수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰린다는 점을 확인했다.",
          "task": "인수인계 체크리스트에 진통제 투여 시각과 보행 보조 여부를 넣자고 제안했다.",
          "action": "두 정보를 인수인계 항목으로 고른 근거를 당시 확인한 문제와 연결해 설명한다.",
          "result": "선택한 항목이 다음 근무자의 환자 상태 파악과 간호에 필요한 정보인 이유가 드러난다."
        },
        "expectedEvidence": [
          "진통제 투여 시각과 보행 보조 여부를 인수인계 항목으로 고른 근거",
          "근무 교대 시간대에 낙상이 몰렸다는 사고 보고서의 정보",
          "선택한 항목과 다음 근무자에게 필요한 환자 정보의 연결"
